import sys, os, subprocess, shlex, optparse, logging, traceback
import re
import tempfile

VERSION_FORMAT = """
/* DO NOT EDIT!  This is an autogenerated file.  See scripts/buildversion.py. */
#define BUILD_VERSION "%s"
#define BUILD_TOOLS "%s"
"""

# Run program and return the specified output
def check_output(prog):
    logging.debug("Running %s" % (repr(prog),))
    try:
        process = subprocess.Popen(shlex.split(prog), stdout=subprocess.PIPE)
        output = process.communicate()[0]
        retcode = process.poll()
    except OSError:
        logging.debug("Exception on run: %s" % (traceback.format_exc(),))
        return ""
    logging.debug("Got (code=%s): %s" % (retcode, repr(output)))
    if retcode:
        return ""
    try:
        return output.decode()
    except UnicodeError:
        logging.debug("Exception on decode: %s" % (traceback.format_exc(),))
        return ""

# Obtain version info from "git" program
def git_version():
    if not os.path.exists('.git'):
        logging.debug("No '.git' file/directory found")
        return ""
    revision = check_output("git rev-parse --verify HEAD").strip()
    if not re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", revision):
        raise RuntimeError("Unable to determine firmware source revision")
    # Fixed width, independent of local tags, shallow history and abbreviation
    # configuration. Track changes to versioned files without host metadata.
    status = subprocess.check_output(
        ["git", "status", "--porcelain", "--untracked-files=no"])
    logging.info("Source revision: %s", revision)
    print("Source revision: %s" % revision)
    return "git-" + revision[:12] + ("-dirty" if status else "")

# Look for version in a ".version" file.  Official release tarballs
# have this file (see scripts/tarball.sh).
def file_version():
    if not os.path.isfile('.version'):
        logging.debug("No '.version' file found")
        return ""
    try:
        f = open('.version', 'r')
        ver = f.readline().strip()
        f.close()
    except OSError:
        logging.debug("Exception on read: %s" % (traceback.format_exc(),))
        return ""
    logging.debug("Got .version: %s" % (repr(ver),))
    return ver

# Encode a C string without allowing a release or distributor name to break
# the generated header. Fixed-width octal escapes cannot absorb following digits.
def c_string(value):
    return "".join(chr(b) if 32 <= b < 127 and b not in (34, 92, 63)
                   else "\\%03o" % b for b in value.encode("utf-8"))


# Keep compiler details in build logs rather than firmware strings.
def write_version(outfile, version):
    toolstr = "see build log"
    content = VERSION_FORMAT % (c_string(version), c_string(toolstr))
    print("Version: %s" % version)
    print("ROM version metadata: %d bytes (including NUL terminators)" %
          (len(version.encode("utf-8")) + len(toolstr.encode("utf-8")) + 2))
    try:
        with open(outfile, "r", encoding="utf-8") as f:
            if f.read() == content:
                return
    except FileNotFoundError:
        pass
    directory = os.path.dirname(os.path.abspath(outfile))
    fd, temporary = tempfile.mkstemp(prefix=".autoversion-", dir=directory)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            f.write(content)
        os.replace(temporary, outfile)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)


def log_tool_versions(tools):
    for tool in tools.split(";"):
        tool = tool.strip()
        if not tool:
            continue
        version = check_output("%s --version" % tool).split("\n")[0]
        print("Build tool: %s: %s" % (tool, version or "version unavailable"))


def main():
    usage = "%prog [options] <outputheader.h>"
    opts = optparse.OptionParser(usage)
    opts.add_option("-e", "--extra", dest="extra", default="",
                    help="extra version string to append to version")
    opts.add_option("-t", "--tools", dest="tools", default="",
                    help="list of build programs to extract version from")
    opts.add_option("-v", action="store_true", dest="verbose",
                    help="enable debug messages")

    options, args = opts.parse_args()
    if len(args) != 1:
        opts.error("Incorrect arguments")
    outfile = args[0]
    if options.verbose:
        logging.basicConfig(level=logging.DEBUG)

    try:
        ver = git_version() or file_version() or "unknown"
        log_tool_versions(options.tools)
        write_version(outfile, ver + options.extra)
    except (OSError, RuntimeError, subprocess.CalledProcessError) as error:
        opts.error(str(error))


if __name__ == '__main__':
    main()
